mapper.select:
SELECT 
FROM source s

WHERE s.source_id = #{sourceId}

where.if:
EXISTS (
    SELECT 1 FROM work_source ws_filter
    WHERE ws_filter.work_id = w.work_id AND ws_filter.source_id = #{sourceId}
)

mapper.select:
SELECT FROM work w JOIN original_file_job j ON j.matched_work_id = w.work_id JOIN block b ON b.file_id = j.file_id
WHERE w.work_id = #{workId}
AND b.block_type != 'discarded'
GROUP BY ORDER BY b.block_seq ASC LIMIT #{limit} OFFSET #{offset}

SELECT FROM block b
WHERE b.file_id = #{fileId}
AND b.block_type != 'discarded'
GROUP BY ORDER BY b.block_seq ASC LIMIT #{limit} OFFSET #{offset}
